/** Every API area, keyed by its OpenAPI tag. */
export interface FastnApis {
  /** Activity (3 operations) */
  activity: ActivityApi;
  /** Agent (22 operations) */
  agent: AgentApi;
  /** API Keys (4 operations) */
  apiKeys: ApiKeysApi;
  /** Auth (3 operations) */
  auth: AuthApi;
  /** Billing (18 operations) */
  billing: BillingApi;
  /** Connections (14 operations) */
  connections: ConnectionsApi;
  /** Connectors (102 operations) */
  connectors: ConnectorsApi;
  /** Embed (45 operations) */
  embed: EmbedApi;
  /** Environments (10 operations) */
  environments: EnvironmentsApi;
  /** Events (68 operations) */
  events: EventsApi;
  /** Execution (5 operations) */
  execution: ExecutionApi;
  /** Observe (14 operations) */
  observe: ObserveApi;
  /** Onboarding (12 operations) */
  onboarding: OnboardingApi;
  /** Orgs (22 operations) */
  orgs: OrgsApi;
  /** Sync (5 operations) */
  sync: SyncApi;
  /** Teams (5 operations) */
  teams: TeamsApi;
  /** Unified API (24 operations) */
  unified: UnifiedApi;
  /** Users (25 operations) */
  users: UsersApi;
  /** Workflows (60 operations) */
  workflows: WorkflowsApi;
}

export function buildApis(t: Transport): FastnApis {
  return {
    activity: new ActivityApi(t),
    agent: new AgentApi(t),
    apiKeys: new ApiKeysApi(t),
    auth: new AuthApi(t),
    billing: new BillingApi(t),
    connections: new ConnectionsApi(t),
    connectors: new ConnectorsApi(t),
    embed: new EmbedApi(t),
    environments: new EnvironmentsApi(t),
    events: new EventsApi(t),
    execution: new ExecutionApi(t),
    observe: new ObserveApi(t),
    onboarding: new OnboardingApi(t),
    orgs: new OrgsApi(t),
    sync: new SyncApi(t),
    teams: new TeamsApi(t),
    unified: new UnifiedApi(t),
    users: new UsersApi(t),
    workflows: new WorkflowsApi(t),
  };
}
